        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many allocations are likely needed; with fixed WATER_REQ, treat supply as proxy for competition
    # (We don't know exact water conversion, so use supply bands.)
    supply_band = 0
    if supply >= 22.0:
        supply_band = 2
    elif supply >= 18.0:
        supply_band = 1
    else:
        supply_band = 0

    # Decide target bid
    # If yesterday highest bid was extreme, we must contest more to avoid losing.
    extreme = highest_prev_bid >= DAILY_SALARY * 0.95
    very_high = highest_prev_bid >= DAILY_SALARY * 0.85

    # HP pressure: if low HP or already on no-water streak, increase bid.
    hp_pressure = 0
    if hp <= 2:
        hp_pressure = 3
    elif hp == 3:
        hp_pressure = 2
    elif hp == 4:
        hp_pressure = 1

    if no_water_days >= 2:
        hp_pressure = max(hp_pressure, 2)

    # Base bid by supply band (more supply => we can bid a bit less while still expecting allocation)
    if supply_band == 2:
        base = DAILY_SALARY * 0.55
    elif supply_band == 1:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.75

    if extreme:
        base = max(base, DAILY_SALARY * 0.75)
    elif very_high:
        base = max(base, DAILY_SALARY * 0.70)

    # Adjust with HP pressure
    target = base + (DAILY_SALARY * 0.08 * hp_pressure)

    # If we're already doing okay and supply is high, avoid overbidding
    if hp >= 6 and supply_band == 2:
        target *= 0.85

    # Keep within budget and reasonable caps
    cap = min(budget, DAILY_SALARY * 1.2)
    bid = min(cap, target)

    # If budget is too small, still bid something to prevent total loss
    if bid < 1.0 and budget >= 1.0:
        bid = min(budget, 5.0)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Get yesterday's bids from alive opponents
    yesterday_bids = []
    for opp_id, opp in alive_opponents.items():
        trace = opp.get('previous_trace', {})
        if trace:
            bid = trace.get('bid')
            if bid is not None:
                yesterday_bids.append(bid)

    # Determine aggressive threshold based on water requirement and supply
    aggressive_bid = DAILY_SALARY * 0.9  # 126

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If anyone bid very high, they are likely to bid high again
        if max_prev >= aggressive_bid:
            # Need water badly or low HP? match or slightly exceed
            if hp <= 3 or no_water_days >= 1:
                target = max_prev + 2
            else:
                target = max_prev * 0.5  # be conservative, let them fight
        else:
            # Bids were moderate, we can bid slightly above to ensure water
            target = max_prev + 1.5
    else:
        # No history or no alive opponents? Bid low if safe
        if hp > 5 and no_water_days == 0:
            target = DAILY_SALARY * 0.2
        else:
            target = DAILY_SALARY * 0.5

    # Ensure bid doesn't exceed budget and is non-negative
    bid = max(0, min(budget, target))
    return bid
